SELECT primary_key, applicant, apply_time, money_record_type, record_amount, currency, confirmed_money, confirmed_exchange_rate, remark, final_approve, confirm_time, reject_reason, reject_time, approval_status, signed_contract, record_batch, contract_number, payment_time, enterprise_code, son_enterprise_code FROM ${tableName} WHERE enterprise_code = #{enterpriseCode} AND primary_key IN
#{recordCode}
AND delete_flag = 'f'

mapper.update:
UPDATE ${tableName}
SET delete_flag = 't'
WHERE primary_key = #{model.recordCode}
  AND enterprise_code = #{model.enterpriseCode}

mapper.select:
SELECT monryRecord.primary_key, monryRecord.applicant, monryRecord.apply_time, monryRecord.money_record_type, monryRecord.record_amount, monryRecord.currency, monryRecord.confirmed_money, monryRecord.confirmed_exchange_rate, monryRecord.remark, monryRecord.final_approve, monryRecord.confirm_time, monryRecord.reject_reason, monryRecord.reject_time, monryRecord.approval_status, monryRecord.signed_contract, monryRecord.record_batch, monryRecord.contract_number, monryRecord.payment_time, monryRecord.enterprise_code, sellContract.buyer_name AS opposite FROM ${moneyRecordTableName} monryRecord JOIN ( SELECT signed_contract, buyer_name, state, user_code, contract_time, money_apply_returned, invoice_apply_returned, business_belong FROM ${sellContractTableName} WHERE 1=1
AND state IN
#{state}
AND user_code IN
#{userCode}
AND buyer_name LIKE '%'|| #{buyerName} ||'%'
AND buyer_name = #{oppositeUnique}
AND contract_time >= #{contractTimePreDate}
AND contract_time <= #{contractTimePostDate}
AND (money_apply_returned = true OR invoice_apply_returned = true)
AND COALESCE(money_apply_returned, false) = false AND COALESCE(invoice_apply_returned, false) = false
AND business_belong = #{businessBelong}
${dataScopeParams.dataScope}
) sellContract ON sellContract.signed_contract = monryRecord.signed_contract WHERE monryRecord.enterprise_code = #{enterpriseCode} AND monryRecord.delete_flag = 'f' AND monryRecord.approval_status = 'CONFIRMED' AND monryRecord.money_record_type = #{moneyRecordType}
AND monryRecord.contract_number LIKE '%'|| #{contractNumber} ||'%'
ORDER BY monryRecord.id DESC

SELECT monryRecord.primary_key, monryRecord.applicant, monryRecord.apply_time, monryRecord.money_record_type, monryRecord.record_amount, monryRecord.currency, monryRecord.confirmed_money, monryRecord.confirmed_exchange_rate, monryRecord.remark, monryRecord.final_approve, monryRecord.confirm_time, monryRecord.reject_reason, monryRecord.reject_time, monryRecord.approval_status, monryRecord.signed_contract, monryRecord.record_batch, monryRecord.contract_number, monryRecord.payment_time, monryRecord.enterprise_code, historyPrice.opposite AS opposite FROM ${moneyRecordTableName} monryRecord INNER JOIN ( SELECT DISTINCT ON (hp.signed_contract) hp.signed_contract, hp.opposite, hp.material_code, hp.material_name, hp.material_model, hp.staff, hp.payment_strategy, hp.record_time, hp.type FROM ${historyPriceTableName} hp
INNER JOIN ${productPartTableName} pp ON pp.primary_key = hp.material_code
WHERE hp.type = 1
AND hp.opposite LIKE '%'|| #{opposite} ||'%'
AND hp.opposite = #{oppositeUnique}
AND (hp.material_name LIKE '%'|| #{searchName} ||'%' OR hp.material_model LIKE '%'|| #{searchName} ||'%')
AND hp.staff IN
#{code}
AND hp.payment_strategy = #{paymentStrategy}
AND hp.record_time >= #{recordTimePreDate}
AND hp.record_time <= #{recordTimePostDate}
AND pp.unity_no LIKE '%'|| #{partUnityNo} ||'%'
${dataScopeParams.dataScope}
ORDER BY hp.signed_contract, hp.id DESC ) historyPrice ON historyPrice.signed_contract = monryRecord.signed_contract WHERE monryRecord.enterprise_code = #{enterpriseCode} AND monryRecord.delete_flag = 'f' AND monryRecord.approval_status = 'CONFIRMED' AND monryRecord.money_record_type = #{moneyRecordType}
AND monryRecord.contract_number LIKE '%'|| #{contractNumber} ||'%'
ORDER BY monryRecord.id DESC

SELECT primary_key, applicant, apply_time, money_record_type, record_amount, currency, confirmed_money, confirmed_exchange_rate, remark, final_approve, confirm_time, reject_reason, reject_time, approval_status, signed_contract,record_batch,contract_number, payment_time, enterprise_code FROM ${tableName} WHERE enterprise_code = #{enterpriseCode} AND signed_contract IN
#{signedContractCode}
AND delete_flag = 'f'
AND applicant IN
#{applicant}

SELECT SUM(COALESCE(confirmed_money, record_amount)) AS data
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
AND signed_contract IN

    #{signedContractCode}

AND approval_status = 'CONFIRMED'
  AND delete_flag = 'f'

SELECT SUM(COALESCE(confirmed_money, record_amount)) AS confirmedAmountSum, signed_contract as signedContract
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
AND signed_contract IN

    #{signedContractCode}

AND approval_status = 'CONFIRMED'
AND delete_flag = 'f'
GROUP BY signed_contract

SELECT COUNT(*)
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
AND signed_contract = #{signedContractCode}
AND approval_status = #{status}
AND delete_flag = 'f'

SELECT COUNT(*) AS confirmingStatusDataCount, signed_contract as signedContract
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
AND signed_contract IN

    #{signedContractCode}

AND approval_status = #{status}
AND delete_flag = 'f'
GROUP BY signed_contract

SELECT a.primary_key, a.applicant, a.apply_time, a.money_record_type, a.record_amount, a.confirmed_money, a.currency, a.confirmed_exchange_rate, a.remark, a.final_approve, a.confirm_time, a.reject_reason, a.reject_time, a.approval_status, a.signed_contract, a.record_batch, a.contract_number, a.payment_time, a.enterprise_code, b.counterpart AS opposite FROM ${moneyRecordTable} a LEFT JOIN ${signedContractTable} b ON a.signed_contract = b.primary_key WHERE b.enterprise_code = #{enterpriseCode}
AND b.counterpart LIKE '%'|| #{opposite} ||'%'
AND b.delete_flag = 'f' AND a.enterprise_code = #{enterpriseCode} AND a.approval_status = 'CONFIRMED' AND a.money_record_type = 'COLLECT' AND a.delete_flag = 'f'
AND a.confirm_time >= #{startDate}
AND a.confirm_time <= #{endDate}
ORDER BY a.confirm_time DESC

SELECT a.primary_key, a.applicant, a.apply_time, a.money_record_type, a.record_amount, a.confirmed_money, a.currency, a.confirmed_exchange_rate, a.remark, a.final_approve, a.confirm_time, a.reject_reason, a.reject_time, a.approval_status, a.signed_contract, a.record_batch, a.contract_number, a.payment_time, a.enterprise_code, b.counterpart AS opposite FROM ${moneyRecordTable} a LEFT JOIN ${signedContractTable} b ON a.signed_contract = b.primary_key WHERE b.enterprise_code = #{enterpriseCode}
AND b.counterpart LIKE '%'|| #{opposite} ||'%'
AND b.delete_flag = 'f' AND a.enterprise_code = #{enterpriseCode} AND a.approval_status = 'CONFIRMED' AND a.delete_flag = 'f' AND a.money_record_type = 'PAYMENT'
AND a.confirm_time >= #{startDate}
AND a.confirm_time <= #{endDate}
ORDER BY a.confirm_time DESC

SELECT SUM(COALESCE(a.confirmed_money, a.record_amount)) AS collectSum FROM ${moneyRecordTable} a LEFT JOIN ${signedContractTable} b ON a.signed_contract = b.primary_key WHERE b.enterprise_code = #{enterpriseCode}
AND b.counterpart LIKE '%'|| #{opposite} ||'%'
AND b.delete_flag = 'f' AND a.enterprise_code = #{enterpriseCode} AND a.approval_status = 'CONFIRMED' AND a.delete_flag = 'f' AND a.money_record_type = 'COLLECT'
AND a.confirm_time >= #{startDate}
AND a.confirm_time <= #{endDate}

SELECT SUM(COALESCE(a.confirmed_money, a.record_amount)) AS paymentSum FROM ${moneyRecordTable} a LEFT JOIN ${signedContractTable} b ON a.signed_contract = b.primary_key WHERE b.enterprise_code = #{enterpriseCode}
AND b.counterpart LIKE '%'|| #{opposite} ||'%'
AND b.delete_flag = 'f' AND a.enterprise_code = #{enterpriseCode} AND a.approval_status = 'CONFIRMED' AND a.delete_flag = 'f' AND a.money_record_type = 'PAYMENT'
AND a.confirm_time >= #{startDate}
AND a.confirm_time <= #{endDate}

mapper.update:
UPDATE ${tableName}
SET contract_number = #{contractNumber}
WHERE signed_contract = #{signedContract}
  AND enterprise_code = #{enterpriseCode}

mapper.select:
SELECT record.primary_key, record.applicant, record.apply_time, record.money_record_type, record.record_amount, record.currency, record.confirmed_money, record.confirmed_exchange_rate, record.remark, record.final_approve, record.confirm_time, record.reject_reason, record.reject_time, record.approval_status, record.signed_contract, record.record_batch, record.contract_number, record.payment_time, record.enterprise_code, contract.counterpart AS opposite FROM ${recordTableName} record LEFT JOIN ${signedContractTable} contract ON record.signed_contract = contract.primary_key WHERE record.enterprise_code = #{enterpriseCode} AND record.delete_flag = 'f' AND record.approval_status != 'WITHDRAWN'
AND contract.counterpart LIKE '%'|| #{opposite} ||'%'
AND record.contract_number LIKE '%'|| #{contractNumber} ||'%'
AND contract.user_code IN
#{userCode}
AND record.applicant IN
#{applicant}
AND record.approval_status IN
#{approveState}
AND record.payment_time IS NOT NULL AND record.payment_time >= #{paymentTimePre}
AND record.payment_time IS NOT NULL AND record.payment_time <= #{paymentTimePost}
ORDER BY record.id DESC
